<?php
namespace App\Services\Payments;
use App\Models\Purchase;use App\Models\SupplierPayment;use App\Services\Accounting\AccountingService;use App\Services\SupplierLedgerService;use App\Support\DocumentNumber;use Illuminate\Support\Facades\DB;use RuntimeException;
class SupplierPaymentService
{
    public function __construct(private SupplierLedgerService $ledger,private AccountingService $accounting){}
    public function create(array $data): SupplierPayment{return DB::transaction(function()use($data){$amount=(float)$data['amount'];if($amount<=0)throw new RuntimeException('Payment amount must be greater than zero.');$purchase=null;if(!empty($data['purchase_id'])){$purchase=Purchase::query()->lockForUpdate()->findOrFail($data['purchase_id']);if($purchase->supplier_id!=(int)$data['supplier_id'])throw new RuntimeException('Purchase does not belong to selected supplier.');if($amount>(float)$purchase->due_amount)throw new RuntimeException('Payment exceeds purchase due amount.');}$p=SupplierPayment::create(['payment_no'=>DocumentNumber::temporary('PAY'),'supplier_id'=>$data['supplier_id'],'purchase_id'=>$data['purchase_id']??null,'account_id'=>$data['account_id'],'payment_date'=>$data['payment_date'],'amount'=>$amount,'method'=>$data['method']??'cash','reference'=>$data['reference']??null,'notes'=>$data['notes']??null,'status'=>'posted','created_by'=>auth()->id()]);$p->update(['payment_no'=>DocumentNumber::final('PAY',$p->id)]);$p->load('supplier','account');$this->ledger->debit($p->supplier,$amount,'payment',$p->payment_no,'Supplier payment','supplier_payment',$p->id,$p->payment_date->toDateString());$this->accounting->post('supplier_payment',$p->id,$p->payment_no,$p->payment_date->toDateString(),'Supplier payment '.$p->payment_no,[['account_code'=>'2000','debit'=>$amount,'credit'=>0,'party_type'=>'supplier','party_id'=>$p->supplier_id],['account_id'=>$p->account_id,'debit'=>0,'credit'=>$amount]]);if($purchase){$purchase->paid_amount=(float)$purchase->paid_amount+$amount;$purchase->due_amount=max(0,(float)$purchase->grand_total-(float)$purchase->paid_amount);$purchase->save();}return $p;});}
}
